(()=>{const buttons=[...document.querySelectorAll('[data-start-step]')],panels=[...document.querySelectorAll('.start-panel')];let current=0;const previous=document.getElementById('start-back'),next=document.getElementById('start-next');function show(index,focus=true){current=Math.max(0,Math.min(4,index));panels.forEach((panel,i)=>panel.hidden=i!==current);buttons.forEach((button,i)=>{if(i===current)button.setAttribute('aria-current','step');else button.removeAttribute('aria-current');});previous.disabled=current===0;next.hidden=current===4;document.getElementById('start-count').textContent=`${current+1} of 5`;if(focus){panels[current].querySelector('h2').focus({preventScroll:true});panels[current].scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}history.replaceState(null,'','#step-'+(current+1));}buttons.forEach((b,i)=>b.addEventListener('click',()=>show(i)));previous.addEventListener('click',()=>show(current-1));next.addEventListener('click',()=>show(current+1));const match=location.hash.match(/^#step-([1-5])$/);show(match?Number(match[1])-1:0,false);})();
